def compute(vars):
    total_deferred = vars["v1"]
    total_contingent = vars["v2"]

    if total_contingent == 0:
        return None

    portion = total_deferred / total_contingent

    return {
        "value": portion,
        "trace": {
            "total_deferred_acquisition_payments": total_deferred,
            "total_contingent_acquisition_payments": total_contingent,
            "portion": portion,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
